def conferir_schema_d60(conexao):
    nomes={n for (n,) in conexao.execute("SELECT name FROM sqlite_master WHERE type='table'")}
    presentes=nomes & set(DDL_D60)
    if not presentes:return False
    if presentes!=set(DDL_D60):raise RuntimeError('Estrutura D60 parcial; banco preservado.')
    normal=lambda s:''.join(s.split()).lower()
    for nome,ddl in {**DDL_D60,**INDICES_D60}.items():
        row=conexao.execute('SELECT sql FROM sqlite_master WHERE name=?',(nome,)).fetchone()
        if not row or not row[0] or normal(row[0])!=normal(ddl):raise RuntimeError('Estrutura D60 divergente; preservado: '+nome)
    cfg=conexao.execute('SELECT id,revision,ativada_em,segredo_verificacao FROM configuracao_preco_d60').fetchall()
    if cfg:
        if len(cfg)!=1 or cfg[0][0]!=1 or cfg[0][1]!=REVISION_D60:raise RuntimeError('Ativação D60 divergente; banco preservado.')
        try:
            data=datetime.fromisoformat(cfg[0][2].replace('Z','+00:00'))
            if data.tzinfo is None or len(bytes.fromhex(cfg[0][3]))!=32:raise ValueError()
        except (ValueError,TypeError):raise RuntimeError('Configuração D60 inválida; banco preservado.') from None
    elif any(conexao.execute('SELECT count(*) FROM '+identidade_sql(n)).fetchone()[0] for n in ('formacoes_preco_cotacao','eventos_formacao_preco')):
        raise RuntimeError('Preços D60 sem ativação correspondente; registros preservados.')
    return True

def ativar_d60(banco,antes):
    from datetime import timezone
    import secrets
    with closing(sqlite3.connect(banco,timeout=30)) as c:
        c.execute('PRAGMA foreign_keys=ON');c.execute('BEGIN IMMEDIATE')
        try:
            if historico(c)!=antes:raise RuntimeError('Banco mudou antes da ativação D60; registros externos preservados.')
            existente=conferir_schema_d60(c)
            if not existente:
                for sql in DDL_D60.values():c.execute(sql)
                for sql in INDICES_D60.values():c.execute(sql)
            cfg=c.execute('SELECT id,revision,ativada_em,segredo_verificacao FROM configuracao_preco_d60').fetchone()
            criada=None
            if cfg is None:
                criada=(1,REVISION,datetime.now(timezone.utc).isoformat(timespec='microseconds'),secrets.token_hex(32))
                c.execute('INSERT INTO configuracao_preco_d60 (id,revision,ativada_em,segredo_verificacao) VALUES (?,?,?,?)',criada)
            conferir_schema_d60(c)
            antigas=[n for n in antes if n not in DDL_D60]
            if historico(c,antigas)!={n:antes[n] for n in antigas}:raise RuntimeError('Histórico anterior divergente antes da ativação; banco preservado.')
            if c.execute('PRAGMA integrity_check').fetchall()!=[('ok',)] or c.execute('PRAGMA foreign_key_check').fetchall():raise RuntimeError('Integridade D60 não confirmada.')
            c.commit()
            return {'tabelas_criadas':0 if existente else 3,'configuracao_criada':criada}
        except BaseException:c.rollback();raise

def desfazer_ativacao_d60(banco,ativacao):
    if ativacao is None or ativacao['configuracao_criada'] is None:return True
    with closing(sqlite3.connect(banco,timeout=30)) as c:
        c.execute('PRAGMA foreign_keys=ON');c.execute('BEGIN IMMEDIATE')
        try:
            conferir_schema_d60(c)
            cfg=c.execute('SELECT id,revision,ativada_em,segredo_verificacao FROM configuracao_preco_d60').fetchone()
            if cfg!=ativacao['configuracao_criada'] or any(c.execute('SELECT count(*) FROM '+identidade_sql(n)).fetchone()[0] for n in ('formacoes_preco_cotacao','eventos_formacao_preco')):
                c.rollback();return False
            if ativacao['tabelas_criadas']:
                for nome in reversed(tuple(DDL_D60)):c.execute('DROP TABLE '+identidade_sql(nome))
            else:c.execute('DELETE FROM configuracao_preco_d60 WHERE id=1')
            c.commit();return True
        except BaseException:c.rollback();raise

