DDL_D61 = {'configuracao_despesas_d61': 'CREATE TABLE configuracao_despesas_d61 (\n\tid INTEGER NOT NULL, \n\trevision VARCHAR(100) NOT NULL, \n\tativada_em VARCHAR(40) NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT ck_configuracao_despesas_id CHECK (id=1)\n)', 'despesas_administracao': "CREATE TABLE despesas_administracao (\n\tid INTEGER NOT NULL, \n\tcontratacao_id INTEGER NOT NULL, \n\tcategoria VARCHAR(16) NOT NULL, \n\tdescricao VARCHAR(300) NOT NULL, \n\tvalor_centavos INTEGER NOT NULL, \n\tpaga_em VARCHAR(10) NOT NULL, \n\treferencia VARCHAR(200) NOT NULL, \n\tstatus VARCHAR(12) NOT NULL, \n\tusuario_admin_id INTEGER NOT NULL, \n\tadministrador_nome VARCHAR(120) NOT NULL, \n\tregistro_interno TEXT NOT NULL, \n\tcriada_em VARCHAR(40) NOT NULL, \n\testornada_em VARCHAR(40), \n\tPRIMARY KEY (id), \n\tCONSTRAINT ck_despesa_categoria CHECK (categoria IN ('coleta','transporte','frete','embalagem','inspecao','outros')), \n\tCONSTRAINT ck_despesa_valor CHECK (valor_centavos>0 AND valor_centavos<=99999999999999), \n\tCONSTRAINT ck_despesa_estado CHECK ((status='confirmada' AND estornada_em IS NULL) OR (status='estornada' AND estornada_em IS NOT NULL)), \n\tFOREIGN KEY(contratacao_id) REFERENCES contratacoes_servico (id)\n)", 'eventos_despesas_administracao': "CREATE TABLE eventos_despesas_administracao (\n\tid INTEGER NOT NULL, \n\tcontratacao_id INTEGER NOT NULL, \n\tdespesa_id INTEGER NOT NULL, \n\tversao INTEGER NOT NULL, \n\tacao VARCHAR(12) NOT NULL, \n\tusuario_admin_id INTEGER NOT NULL, \n\tadministrador_nome VARCHAR(120) NOT NULL, \n\tregistro_interno TEXT NOT NULL, \n\treferencia VARCHAR(200) NOT NULL, \n\tcriado_em VARCHAR(40) NOT NULL, \n\tchave_operacao VARCHAR(36) NOT NULL, \n\tpedido_sha256 VARCHAR(64) NOT NULL, \n\tresultado_json TEXT NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_evento_despesa_versao UNIQUE (contratacao_id, versao), \n\tCONSTRAINT ck_evento_despesa_acao CHECK (acao IN ('registrar','estornar') AND versao>0), \n\tFOREIGN KEY(contratacao_id) REFERENCES contratacoes_servico (id), \n\tFOREIGN KEY(despesa_id) REFERENCES despesas_administracao (id), \n\tUNIQUE (chave_operacao)\n)"}

INDICES_D61 = {'ix_despesas_administracao_contratacao_id': 'CREATE INDEX ix_despesas_administracao_contratacao_id ON despesas_administracao (contratacao_id)', 'ix_eventos_despesas_administracao_contratacao_id': 'CREATE INDEX ix_eventos_despesas_administracao_contratacao_id ON eventos_despesas_administracao (contratacao_id)', 'ix_eventos_despesas_administracao_despesa_id': 'CREATE INDEX ix_eventos_despesas_administracao_despesa_id ON eventos_despesas_administracao (despesa_id)'}

def conferir_schema_d61(conexao):
    nomes={n for (n,) in conexao.execute("SELECT name FROM sqlite_master WHERE type='table'")}
    presentes=nomes & set(DDL_D61)
    if not presentes:return False
    if presentes!=set(DDL_D61):raise RuntimeError('Estrutura D61 parcial; banco preservado.')
    normal=lambda s:''.join(s.split()).lower()
    for nome,ddl in {**DDL_D61,**INDICES_D61}.items():
        r=conexao.execute('SELECT sql FROM sqlite_master WHERE name=?',(nome,)).fetchone()
        if not r or not r[0] or normal(r[0])!=normal(ddl):raise RuntimeError('Estrutura D61 divergente; preservado: '+nome)
    cfg=conexao.execute('SELECT id,revision,ativada_em FROM configuracao_despesas_d61').fetchall()
    if cfg:
        if len(cfg)!=1 or cfg[0][0]!=1 or cfg[0][1]!=REVISION:raise RuntimeError('Ativação D61 divergente; banco preservado.')
        try:
            data=datetime.fromisoformat(cfg[0][2].replace('Z','+00:00'))
            if data.tzinfo is None:raise ValueError()
        except (ValueError,TypeError):raise RuntimeError('Configuração D61 inválida; banco preservado.') from None
    elif any(conexao.execute('SELECT count(*) FROM '+identidade_sql(n)).fetchone()[0] for n in ('despesas_administracao','eventos_despesas_administracao')):
        raise RuntimeError('Despesas D61 sem ativação; registros preservados.')
    return True

def ativar_d61(banco,antes):
    from datetime import timezone
    with closing(sqlite3.connect(banco,timeout=30)) as c:
        c.execute('PRAGMA foreign_keys=ON');c.execute('BEGIN IMMEDIATE')
        try:
            if historico(c)!=antes:raise RuntimeError('Banco mudou antes da ativação D61; registros externos preservados.')
            existente=conferir_schema_d61(c)
            if not existente:
                for sql in DDL_D61.values():c.execute(sql)
                for sql in INDICES_D61.values():c.execute(sql)
            cfg=c.execute('SELECT id,revision,ativada_em FROM configuracao_despesas_d61').fetchone();criada=None
            if cfg is None:
                criada=(1,REVISION,datetime.now(timezone.utc).isoformat(timespec='microseconds'))
                c.execute('INSERT INTO configuracao_despesas_d61 (id,revision,ativada_em) VALUES (?,?,?)',criada)
            conferir_schema_d61(c)
            antigas=[n for n in antes if n not in DDL_D61]
            if historico(c,antigas)!={n:antes[n] for n in antigas}:raise RuntimeError('Histórico anterior divergente; banco preservado.')
            if c.execute('PRAGMA integrity_check').fetchall()!=[('ok',)] or c.execute('PRAGMA foreign_key_check').fetchall():raise RuntimeError('Integridade D61 não confirmada.')
            c.commit();return {'tabelas_criadas':0 if existente else 3,'configuracao_criada':criada}
        except BaseException:c.rollback();raise

def desfazer_ativacao_d61(banco,ativacao):
    if ativacao is None or ativacao['configuracao_criada'] is None:return True
    with closing(sqlite3.connect(banco,timeout=30)) as c:
        c.execute('PRAGMA foreign_keys=ON');c.execute('BEGIN IMMEDIATE')
        try:
            conferir_schema_d61(c)
            cfg=c.execute('SELECT id,revision,ativada_em FROM configuracao_despesas_d61').fetchone()
            if cfg!=ativacao['configuracao_criada'] or any(c.execute('SELECT count(*) FROM '+identidade_sql(n)).fetchone()[0] for n in ('despesas_administracao','eventos_despesas_administracao')):
                c.rollback();return False
            if ativacao['tabelas_criadas']:
                for nome in reversed(tuple(DDL_D61)):c.execute('DROP TABLE '+identidade_sql(nome))
            else:c.execute('DELETE FROM configuracao_despesas_d61 WHERE id=1')
            c.commit();return True
        except BaseException:c.rollback();raise


